    /**
     * Tests creating a new Category.
     *
     * @return    Category
     */
    public Category testCreate() throws Throwable {
    Category entity = null;

    LOGGER.info( "CategoryTest:testCreate()" );
    LOGGER.info( "-- Attempting to create a Category");

    StringBuilder msg = new StringBuilder( "-- Failed to create a Category" );

    try {
        entity = service.createCategory( generateNewCommand() );
        assertNotNull( entity, msg.toString() );

        theId = entity.getCategoryId();
        assertNotNull( theId, msg.toString() + " Contains a null primary key" );

        LOGGER.info( "-- Successfully created a Category with primary key" + theId );
    }
    catch (Exception e)  {
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() + entity );

        throw e;
    }
    return entity;
}

