    public Category testUpdate() throws Throwable {
    LOGGER.info( "CategoryTest:testUpdate()" );
    LOGGER.info( "-- Attempting to update a Category." );

    StringBuilder msg = new StringBuilder( "Failed to update a Category : " );
    Category entity = null;

    try {
        UpdateCategoryCommand updateCommand = this.generateUpdateCommand();

        // apply the current id as to update the fields of the current entity
        updateCommand.setCategoryId( theId );

        assertNotNull( updateCommand, msg.toString() );

        LOGGER.info( "-- Now updating the created Category." );

        entity = service.updateCategory( updateCommand );

        assertNotNull( entity, msg.toString()  );

        LOGGER.info( "-- Successfully saved Category - " + entity.toString() );
    }
    catch ( Throwable e ) {
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() + " : primarykey-" + theId + " : entity-" +  entity + " : " + e );

        throw e;
    }

    return( entity );
}

