    /**
     * Tests getting all Categorys.
     *
     * @return    Collection
     */
    public List<Category> testGetAll() throws Throwable {
    LOGGER.info( "CategoryTest:testGetAll() - Retrieving Collection of Categorys:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all Category : " );
    List<Category> collection  = null;

    try {
        // call the static get method on the CategoryService
        collection = service.getAllCategory();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            Category currEntity  = null;
            Iterator<Category> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getCategoryId(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

